from handler import DataHandler


class TestDataHandlerTransform:
    """测试 DataHandler 类的 transform 方法"""

    # ===== 正常用例 =====
    def test_transform_normal_dict_upper(self):
        """测试普通字典使用upper函数转换"""
        handler = DataHandler(source="test_source")
        handler.data = {"name": "john", "city": "beijing"}
        result = handler.transform(str.upper)
        assert result == {"name": "JOHN", "city": "BEIJING"}

    def test_transform_normal_dict_len(self):
        """测试普通字典使用len函数转换"""
        handler = DataHandler(source="test_source")
        handler.data = {"a": "hello", "bb": "world", "ccc": "test"}
        result = handler.transform(len)
        assert result == {"a": 5, "bb": 5, "ccc": 4}

    def test_transform_custom_function(self):
        """测试自定义转换函数"""
        handler = DataHandler(source="test_source")
        handler.data = {"x": 10, "y": 20}
        result = handler.transform(lambda v: v * 2)
        assert result == {"x": 20, "y": 40}

    def test_transform_identity_function(self):
        """测试恒等函数转换"""
        handler = DataHandler(source="test_source")
        handler.data = {"key1": "value1", "key2": "value2"}
        result = handler.transform(lambda x: x)
        assert result == {"key1": "value1", "key2": "value2"}

    # ===== 边界用例 =====
    def test_transform_empty_dict(self):
        """测试空字典"""
        handler = DataHandler(source="test_source")
        handler.data = {}
        result = handler.transform(str.upper)
        assert result == {}

    def test_transform_single_key(self):
        """测试单元素字典"""
        handler = DataHandler(source="test_source")
        handler.data = {"only": "item"}
        result = handler.transform(str.upper)
        assert result == {"only": "ITEM"}

    def test_transform_with_none_values(self):
        """测试值为None的情况"""
        handler = DataHandler(source="test_source")
        handler.data = {"key": None}
        result = handler.transform(str)
        assert result == {"key": "None"}

    def test_transform_with_numeric_values(self):
        """测试数值类型数据"""
        handler = DataHandler(source="test_source")
        handler.data = {"age": 25, "score": 100.5}
        result = handler.transform(str)
        assert result == {"age": "25", "score": "100.5"}

    def test_transform_with_empty_string(self):
        """测试空字符串值"""
        handler = DataHandler(source="test_source")
        handler.data = {"empty": ""}
        result = handler.transform(str.upper)
        assert result == {"empty": ""}

    # ===== 异常用例 =====
    def test_transform_function_raises_exception(self):
        """测试转换函数抛出异常"""
        handler = DataHandler(source="test_source")
        handler.data = {"number": 123}
        with pytest.raises(AttributeError):
            handler.transform(lambda x: x.upper())

    def test_transform_invalid_function_type(self):
        """测试传入无效函数类型"""
        handler = DataHandler(source="test_source")
        handler.data = {"key": "value"}
        with pytest.raises(TypeError):
            handler.transform("not_a_function")

    def test_transform_division_by_zero(self):
        """测试除零异常"""
        handler = DataHandler(source="test_source")
        handler.data = {"zero": 0, "num": 10}
        with pytest.raises(ZeroDivisionError):
            handler.transform(lambda x: 10 / x)

