class TestFormatOutputNormal:
    """正常用例：常见类型的输入"""

    def test_string(self):
        assert format_output("hello") == "hello"

    def test_integer(self):
        assert format_output(123) == "123"

    def test_float(self):
        assert format_output(3.14) == "3.14"

    def test_boolean_true(self):
        assert format_output(True) == "True"

    def test_boolean_false(self):
        assert format_output(False) == "False"

    def test_list(self):
        assert format_output([1, 2, 3]) == "[1, 2, 3]"

    def test_dict(self):
        assert format_output({"a": 1}) == "{'a': 1}"

    def test_none(self):
        assert format_output(None) == "None"

    def test_string_with_surrounding_whitespace(self):
        assert format_output("  hello world  ") == "hello world"

    def test_newlines_and_tabs(self):
        assert format_output("\n\tHello\t\n") == "Hello"

    def test_unicode(self):
        assert format_output("你好，世界！") == "你好，世界！"

    def test_bytes(self):
        # str(b'...') 的默认表现
        assert format_output(b"hello") == "b'hello'"

    def test_tuple(self):
        assert format_output((1, 2)) == "(1, 2)"

    def test_set(self):
        # set 的顺序不确定，只检查结果是否被正确 strip
        result = format_output({3, 1, 2})
        assert result == result.strip() and result.startswith("{") and result.endswith("}")


class TestFormatOutputEdge:
    """边界用例：极端或特殊情况的输入"""

    def test_empty_string(self):
