class TestProcessData:
    # ---- Normal cases -----------------------------------------------------
    @pytest.mark.parametrize(
        "data, expected",
        [
            ({"name": "Alice"}, {"name": "ALICE"}),
            ({"a": 1, "b": 2}, {"a": "1", "b": "2"}),
            (
                {"val": 3.14, "flag": True, "none": None},
                {"val": "3.14", "flag": "TRUE", "none": "NONE"},
            ),
            ({"list": [1, 2, 3]}, {"list": "[1, 2, 3]"}),
            (
                {"mixed": "Hello", "int": 0, "float": -5.5e-3},
                {"mixed": "HELLO", "int": "0", "float": "-0.0055"},
            ),
        ],
    )
    def test_process_data_normal(self, data, expected):
        """Values of various types are correctly converted to uppercase strings."""
        assert process_data(data) == expected

    # ---- Edge cases -------------------------------------------------------
    def test_process_data_empty_dict(self):
        """An empty mapping yields an empty dictionary."""
        assert process_data({}) == {}

    def test_process_data_unicode_uppercase(self):
        """Unicode characters are upper‑cased where applicable."""
        data = {"digit": "7", "greek": "ω"}
        result = process_data(data)
        assert result == {"digit": "7", "greek": "Ω"}

    def test_process_data_special_characters(self):
        """Symbols and punctuation are preserved while letters are upper‑cased."""
        data = {"sym": "αβγ", "punct": "a!b?c"}
        result = process_data(data)
        # Greek letters remain unchanged (no uppercase), ASCII letters become uppercase.
        assert result == {"sym": "ΑΒΓ", "punct": "A!B?C"}

    def test_process_data_non_string_keys(self):
        """Keys that are not strings are kept as‑is while values are processed."""
        data = {1: "value", "2": 2}
        result = process_data(data)
        assert result[1] == "VALUE"
        assert result["2"] == "2"

    def test_process_data_nested_structures(self):
        """Nested structures are stringified but not recursively upper‑cased."""
        data = {"nested": {"inner": "text"}}
        result = process_data(data)
        assert result == {"nested": "{'inner': 'text'}"}

    # ---- Exception cases ---------------------------------------------------
    def test_process_data_non_mapping_list_raises(self):
        """Passing a list (which is not a Mapping) must raise TypeError."""
        with pytest.raises(TypeError):
            process_data([1, 2, 3])

    def test_process_data_non_mapping_str_raises(self):
        """Passing a plain string (also not a Mapping) must raise TypeError."""
        with pytest.raises(TypeError):
            process_data("abc")

    def test_process_data_non_mapping_int_raises(self):
        """Passing an integer must raise TypeError."""
        with pytest.raises(TypeError):
            process_data(123)

    def test_process_data_none_raises(self):
        """Passing None must raise TypeError."""
        with pytest.raises(TypeError):
            process_data(None)


